(6827545, 1026897, 96751, '<td valign="top">Terrific building. I would have liked for there to be a little more separation between the figures and the bg</td>', 'Terrific building. I would have liked for there to be a little more separation between the figures and the bg', '2012-07-25 22:33:10.000000', NULL, 1),
(6827547, 1026489, 96751, '<td valign="top">Lovely balance. I like how the curve of the tree diverges from the curve of the clouds</td>', 'Lovely balance. I like how the curve of the tree diverges from the curve of the clouds', '2012-07-25 22:33:41.000000', NULL, 1),
