(6827551, 1026952, 96751, '<td valign="top">Very "vintage" mood here, and lovely colors, but mostly not a silhouette</td>', 'Very "vintage" mood here, and lovely colors, but mostly not a silhouette', '2012-07-25 22:34:35.000000', NULL, 1),
