(6827557, 1026922, 96751, '<td valign="top">Perfect placement of the glow in the clouds over the helicopter. A very serene mood.</td>', 'Perfect placement of the glow in the clouds over the helicopter. A very serene mood.', '2012-07-25 22:36:23.000000', NULL, 1),
