(6827568, 1026962, 96751, '<td valign="top">Nicely done, though I wish the right half was the same width as the left.</td>', 'Nicely done, though I wish the right half was the same width as the left.', '2012-07-25 22:40:48.000000', NULL, 1),
(6827570, 1026985, 96751, '<td valign="top">Although the island is in silhouette, this image is more about the sky and the horizontal (???!!!) lightning. Gorgeous sky.</td>', 'Although the island is in silhouette, this image is more about the sky and the horizontal (???!!!) lightning. Gorgeous sky.', '2012-07-25 22:41:23.000000', NULL, 1),
(6827571, 1026329, 96751, '<td valign="top">I like the mood, the implied nudity, the location. It doesn''t strike me quite as a silhouette, however.</td>', 'I like the mood, the implied nudity, the location. It doesn''t strike me quite as a silhouette, however.', '2012-07-25 22:42:02.000000', NULL, 1),
(6827572, 1026955, 96751, '<td valign="top">Powerful, simple.</td>', 'Powerful, simple.', '2012-07-25 22:42:22.000000', NULL, 1),
