(6827647, 1027004, 96751, '<td valign="top">This is really emotive. Reminds me of Anita''s work. My favorite part: the texture of the fence in the bg</td>', 'This is really emotive. Reminds me of Anita''s work. My favorite part: the texture of the fence in the bg', '2012-07-25 23:04:24.000000', NULL, 1),
(6827649, 1026773, 96751, '<td valign="top">Amazing detail in that little feather on the right</td>', 'Amazing detail in that little feather on the right', '2012-07-25 23:04:45.000000', NULL, 1),
(6827651, 1026768, 96751, '<td valign="top">Classic</td>', 'Classic', '2012-07-25 23:05:19.000000', NULL, 1),
(6827654, 1027025, 96751, '<td valign="top">Truly terrific classic silhouette.  Looks like Central Park. Awesome textures in the stone</td>', 'Truly terrific classic silhouette.  Looks like Central Park. Awesome textures in the stone', '2012-07-25 23:06:08.000000', NULL, 1),
(6827656, 1026866, 96751, '<td valign="top">Lovely</td>', 'Lovely', '2012-07-25 23:06:42.000000', NULL, 1),
(6827657, 1026401, 96751, '<td valign="top">LOVE this!  Fabulous ghosting</td>', 'LOVE this!  Fabulous ghosting', '2012-07-25 23:07:34.000000', NULL, 1),
(6827658, 1027005, 96751, '<td valign="top">Could be part of a tourist brochure. Classic</td>', 'Could be part of a tourist brochure. Classic', '2012-07-25 23:07:53.000000', NULL, 1),
(6827693, 1027004, 42013, '<td valign="top">One of my favs from this challenge. The backlighting and rim lighting works well. I''d call it a silhouette though you may get some disagreement from others. And I like his "i''m kinda bored with this game" stance.</td>', 'One of my favs from this challenge. The backlighting and rim lighting works well. I''d call it a silhouette though you may get some disagreement from others. And I like his "i''m kinda bored with this game" stance.', '2012-07-25 23:56:34.000000', NULL, 1),
(6827695, 1026927, 42013, '<td valign="top">Special in its simplicity.</td>', 'Special in its simplicity.', '2012-07-25 23:56:51.000000', NULL, 1),
(6827714, 1027036, 149779, '<td valign="top">Great use of negative space.  I love this.</td>', 'Great use of negative space.  I love this.', '2012-07-26 00:17:26.000000', NULL, 1),
(6827733, 1026990, 149779, '<td valign="top">The cut-outs don''t make sense in this image.  It appears to be lit from the top, but the "people" are black as if it is lit from the front.  There are no shadows behind them (to the bottom of the image) in the sand, so the cut-outs just look like miniature paper dolls instead of actual people.</td>', 'The cut-outs don''t make sense in this image.  It appears to be lit from the top, but the "people" are black as if it is lit from the front.  There are no shadows behind them (to the bottom of the image) in the sand, so the cut-outs just look like miniature paper dolls instead of actual people.', '2012-07-26 00:37:50.000000', NULL, 1),
(6827734, 1026996, 149779, '<td valign="top">Mad props for a good title.  And this is totally a silhouette.  I already know you will have other comments saying it isn''t.</td>', 'Mad props for a good title.  And this is totally a silhouette.  I already know you will have other comments saying it isn''t.', '2012-07-26 00:39:21.000000', NULL, 1),
(6827735, 1026681, 149779, '<td valign="top">A more dramatic angle might make this really pop.</td>', 'A more dramatic angle might make this really pop.', '2012-07-26 00:40:29.000000', NULL, 1),
(6827738, 1026948, 149779, '<td valign="top">At least no one (probably) will complain that it isn''t a silhouette.  It does look like vector art though.  I wish there was more interest in color or texture or something.</td>', 'At least no one (probably) will complain that it isn''t a silhouette.  It does look like vector art though.  I wish there was more interest in color or texture or something.', '2012-07-26 00:45:08.000000', NULL, 1),
(6827755, 1026608, 30982, '<td valign="top">An interesting take on a silhouette.  I like the hard edges.</td>', 'An interesting take on a silhouette.  I like the hard edges.', '2012-07-26 01:29:11.000000', NULL, 1),
(6827756, 1026934, 30982, '<td valign="top">Possibly not what folks are looking for as silhouettes, but I like they way they dance!</td>', 'Possibly not what folks are looking for as silhouettes, but I like they way they dance!', '2012-07-26 01:29:32.000000', NULL, 1),
(6827757, 1026928, 30982, '<td valign="top">Excellent.  I have a similar kind of shot from up here - a marvelous place for lovely light, long shadows.  AND you got the Hollywood sign - nice!</td>', 'Excellent.  I have a similar kind of shot from up here - a marvelous place for lovely light, long shadows.  AND you got the Hollywood sign - nice!', '2012-07-26 01:35:08.000000', NULL, 1),
(6827758, 1026996, 30982, '<td valign="top">Love this!  How wonderfully alien.</td>', 'Love this!  How wonderfully alien.', '2012-07-26 01:38:10.000000', NULL, 1),
(6827767, 1026970, 142273, '<td valign="top">This is beautiful capture! One of my favs for the ribbon!</td>', 'This is beautiful capture! One of my favs for the ribbon!', '2012-07-26 02:24:05.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6827768, 1026748, 142273, '<td valign="top">This is a beautiful picture!</td>', 'This is a beautiful picture!', '2012-07-26 02:24:42.000000', NULL, 1),
(6827770, 1026855, 142273, '<td valign="top">This is awesome and smartly done! Thumbs up on execution!</td>', 'This is awesome and smartly done! Thumbs up on execution!', '2012-07-26 02:35:15.000000', NULL, 1),
(6827773, 1026970, 146189, '<td valign="top">Excellent !!!! Love it. 10 from me.</td>', 'Excellent !!!! Love it. 10 from me.', '2012-07-26 02:52:57.000000', NULL, 1),
(6827801, 1026767, 129807, '<td valign="top">I really like the colours and tonal range here. Nicely done.</td>', 'I really like the colours and tonal range here. Nicely done.', '2012-07-26 04:52:47.000000', NULL, 1),
(6827802, 1026478, 129807, '<td valign="top">Terrific detail - and that bg gradation is extremely nice.</td>', 'Terrific detail - and that bg gradation is extremely nice.', '2012-07-26 04:53:44.000000', NULL, 1),
(6827837, 1026625, 7327, '<td valign="top">Beautiful use of light, one of the nicest figure studies Ive seen.</td>', 'Beautiful use of light, one of the nicest figure studies Ive seen.', '2012-07-26 07:35:27.000000', NULL, 1),
(6827838, 1026775, 7327, '<td valign="top">I ;ike how the silhouettes frame the lake, nice, great photo.</td>', 'I ;ike how the silhouettes frame the lake, nice, great photo.', '2012-07-26 07:41:42.000000', NULL, 1),
(6827839, 1026821, 7327, '<td valign="top">Nice use of reflections from the rails.</td>', 'Nice use of reflections from the rails.', '2012-07-26 07:46:54.000000', NULL, 1),
(6827840, 1026813, 7327, '<td valign="top">Really nice shot, its a shame the lake wasnt glass calm to reflect moon.</td>', 'Really nice shot, its a shame the lake wasnt glass calm to reflect moon.', '2012-07-26 07:51:55.000000', NULL, 1),
(6827842, 1026608, 7327, '<td valign="top">Nice use of light, the shadows add so much texture.</td>', 'Nice use of light, the shadows add so much texture.', '2012-07-26 07:55:31.000000', NULL, 1),
(6827843, 1026736, 7327, '<td valign="top">Is this a self-portrait using mirrors?  If so a very nice shot, nice shot even if it isnt actually.</td>', 'Is this a self-portrait using mirrors?  If so a very nice shot, nice shot even if it isnt actually.', '2012-07-26 07:59:22.000000', NULL, 1),
(6827889, 1027027, 149779, '<td valign="top">In my top 3.  Great and well balanced composition, good exposure, great action and motion, good use of foreground bokeh (not easily done) and the silhouette adds something to the composition, which was, in my opinion, the real challenge.  <br/> <br/>I am finding that the real difficulty in this challenge was having the silhouette be a focal point AND add something to the image instead of just being a random item plopped in front of a light source so there would be a silhouette no matter how distracting or useless it was to the overall image.   You are one of a tiny handful who pulled this off.  Well done.</td>', 'In my top 3.  Great and well balanced composition, good exposure, great action and motion, good use of foreground bokeh (not easily done) and the silhouette adds something to the composition, which was, in my opinion, the real challenge.   I am finding that the real difficulty in this challenge was having the silhouette be a focal point AND add something to the image instead of just being a random item plopped in front of a light source so there would be a silhouette no matter how distracting or useless it was to the overall image.   You are one of a tiny handful who pulled this off.  Well done.', '2012-07-26 09:45:23.000000', NULL, 1),
(6827961, 1026625, 149779, '<td valign="top">Beautiful, well lit, well composed, and good use of the challenge.  In my top 10.</td>', 'Beautiful, well lit, well composed, and good use of the challenge.  In my top 10.', '2012-07-26 12:13:10.000000', NULL, 1),
